/**
 * The fan-out hub: one domain event becomes in-app rows, an email draft and/or a digest entry, filtered by each recipient's preferences.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, isEnabled, subscribe
 */
import { subscribe } from "@/lib/event-bus";
import { isEnabled } from "@/lib/feature-flags";
import { assertCan } from "@/lib/permissions";
import { settingsPath } from "@/lib/url";
import { issueHref } from "./_links";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import { toIsoTimestamp } from "@/types/common";
import { notificationResource, requireFound } from "./_support";
import type {
  ListNotificationsInput,
  MarkNotificationReadInput,
  UpdateNotificationPreferenceInput,
} from "@/schemas/notification";
import type { OrgId, Page, UserId } from "@/types/common";
import type { FlagContext } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type {
  Notification,
  NotificationChannel,
  NotificationKind,
  NotificationPreference,
} from "@/types/notification";

export type NotificationPayload = {
  title: string;
  body: string;
  href: string;
  actorId: UserId | null;
};

/** Channels used when a recipient has never touched their preferences. */
const DEFAULT_CHANNELS: readonly NotificationChannel[] = ["in_app", "email"];

/**
 * Writes one notification row per recipient, each with the channel set that
 * recipient's preferences allow. A recipient who has muted every channel is
 * skipped entirely rather than given a row nobody will ever see.
 */
export async function notify(
  orgId: OrgId,
  kind: NotificationKind,
  recipients: readonly UserId[],
  payload: NotificationPayload,
): Promise<readonly Notification[]> {
  if (recipients.length === 0) return [];

  const org = await orgRepo.findOrgById(orgId);
  const flags: FlagContext = {
    orgId,
    userId: payload.actorId,
    plan: org?.plan ?? "free",
    role: null,
    overrides: org?.settings.enabledFlagOverrides,
  };

  const rows = [];

  for (const recipientId of new Set(recipients)) {
    if (recipientId === payload.actorId) continue;

    const preference = await preferenceRepo.getPreference(
      orgId,
      recipientId,
      kind,
    );
    const channels = resolveChannels(preference, flags);
    if (channels.length === 0) continue;

    rows.push({
      orgId,
      recipientId,
      kind,
      title: payload.title,
      body: payload.body,
      href: payload.href,
      actorId: payload.actorId,
      channels,
    });
  }

  return notificationRepo.insertNotifications(orgId, rows);
}

export async function listNotifications(
  actor: Actor,
  input: ListNotificationsInput,
): Promise<Page<Notification>> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:read",
    notificationResource(input.orgId, input.recipientId),
  );
  return notificationRepo.listNotifications(input);
}

export async function markRead(
  actor: Actor,
  input: MarkNotificationReadInput,
): Promise<Notification> {
  assertOrgScope(actor, input.orgId);
  const notification = requireFound(
    await notificationRepo.findNotificationById(input.orgId, input.notificationId),
    "Notification",
    input.notificationId,
  );
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, notification.recipientId),
  );
  return notificationRepo.markRead(
    input.orgId,
    input.notificationId,
    toIsoTimestamp(new Date()),
  );
}

export async function markAllRead(
  actor: Actor,
  orgId: OrgId,
): Promise<number> {
  assertOrgScope(actor, orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(orgId, actor.userId),
  );
  return notificationRepo.markAllRead(
    orgId,
    actor.userId,
    toIsoTimestamp(new Date()),
  );
}

export async function updatePreference(
  actor: Actor,
  input: UpdateNotificationPreferenceInput,
): Promise<NotificationPreference> {
  assertOrgScope(actor, input.orgId);
  assertCan(
    actor,
    "notification:manage",
    notificationResource(input.orgId, input.userId),
  );
  return preferenceRepo.upsertPreference(input);
}

/**
 * Turns a stored preference into the channels one notification will use.
 * `digestOnly` suppresses the immediate email but keeps the in-app row, and
 * the email channel additionally requires the org's `digest_email` plan flag.
 */
export function resolveChannels(
  preference: NotificationPreference | null,
  flags: FlagContext,
): readonly NotificationChannel[] {
  if (preference === null) return DEFAULT_CHANNELS;

  const channels: NotificationChannel[] = [];
  if (preference.inApp) channels.push("in_app");

  const emailAllowed =
    preference.email &&
    (!preference.digestOnly || isEnabled("digest_email", flags));

  if (emailAllowed) channels.push("email");
  return channels;
}

/**
 * The bus wiring. Attached at module load rather than from `event-registry`
 * because the fan-out has no other public entry point — importing this module
 * is what makes an org start receiving notifications.
 */
let registered = false;

function registerFanOut(): void {
  if (registered) return;
  registered = true;

  subscribe("issue.assigned", async (payload) => {
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.overdue", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_overdue", [payload.assigneeId], {
      title: "An issue is overdue",
      body: `Issue ${payload.issueId} was due ${payload.dueAt}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: null,
    });
  });

  subscribe("comment.created", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    const watchers = issue
      ? [issue.authorId, ...(issue.assigneeId ? [issue.assigneeId] : [])]
      : [];

    await notify(payload.orgId, "comment_created", watchers, {
      title: "New comment",
      body: `A comment was added to issue ${payload.issueId}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });

    if (payload.mentionedUserIds.length > 0) {
      await notify(
        payload.orgId,
        "comment_mention",
        payload.mentionedUserIds,
        {
          title: "You were mentioned",
          body: `You were mentioned on issue ${payload.issueId}`,
          href: await issueHref(payload.orgId, payload.issueId),
          actorId: payload.actorId,
        },
      );
    }
  });

  subscribe("member.joined", async (payload) => {
    const org = requireFound(
      await orgRepo.findOrgById(payload.orgId),
      "Organization",
      payload.orgId,
    );
    await notify(payload.orgId, "member_joined", [org.ownerId].filter((id) => id !== payload.userId), {
      title: "A new member joined",
      body: `${payload.userId} joined ${org.name} as ${payload.role}`,
      href: settingsPath(org.slug, "members"),
      actorId: payload.userId,
    });
  });

  subscribe("issue.created", async (payload) => {
    if (payload.assigneeId === null) return;
    await notify(payload.orgId, "issue_assigned", [payload.assigneeId], {
      title: "You were assigned an issue",
      body: `Issue ${payload.issueId} is now yours`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("issue.status_changed", async (payload) => {
    const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
    if (!issue?.assigneeId) return;
    await notify(payload.orgId, "issue_status_changed", [issue.assigneeId], {
      title: "Issue status changed",
      body: `Issue ${payload.issueId} moved from ${payload.from} to ${payload.to}`,
      href: await issueHref(payload.orgId, payload.issueId),
      actorId: payload.actorId,
    });
  });

  subscribe("billing.limit_exceeded", async (payload) => {
    const org = requireFound(await orgRepo.findOrgById(payload.orgId), "Organization", payload.orgId);
    await notify(payload.orgId, "plan_limit_reached", [org.ownerId], {
      title: `Plan limit reached: ${payload.resource}`,
      body: `${payload.used} ${payload.resource} are in use; your plan allows ${payload.limit}`,
      href: settingsPath(org.slug, "billing"),
      // A quota refusal must reach the owner even when they attempted it.
      actorId: null,
    });
  });
}

registerFanOut();
/**
 * Project list with archive filter.
 *
 * Owner D. `?archived=1` flips `includeArchived`, which is the only way an
 * archived project becomes visible again — nothing else in the UI surfaces
 * soft-deleted rows.
 *
 * Must call (do not reimplement): can
 */

import Link from "next/link";
import type { Metadata } from "next";
import { PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { ProjectCard } from "@/components/domain/project/project-card";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import { listProjects } from "@/server/services/project-service";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Projects",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const mayCreate = can(actor, "project:create", {
    kind: "project",
    orgId: org.id,
    projectId: PENDING_PROJECT_ID,
    visibility: "org",
    leadId: actor.userId,
  });

  const pagination = searchParamsPaginationSchema.parse(search);
  const includeArchived = search.archived === "1";

  const page = await listProjects(actor, {
    orgId: org.id,
    query: typeof search.q === "string" ? search.q : undefined,
    includeArchived,
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  return (
    <div className="space-y-8">
      <header className="flex items-baseline justify-between">
        <div>
          <h1 className="text-2xl font-semibold tracking-tight">Projects</h1>
          <p className="mt-1 text-sm text-slate-600">
            {page.total} projects{includeArchived ? ", archived included" : ""}
          </p>
        </div>

        <div className="flex items-center gap-4 text-sm">
          <Link
            href={`/${orgSlug}/projects${includeArchived ? "" : "?archived=1"}`}
            className="text-slate-600"
          >
            {includeArchived ? "Hide archived" : "Show archived"}
          </Link>
          {mayCreate ? (
            <Link
              href={`/${orgSlug}/projects/new`}
              className="rounded-md bg-indigo-600 px-3 py-1.5 font-medium text-white"
            >
              New project
            </Link>
          ) : null}
        </div>
      </header>

      {page.items.length === 0 ? (
        <EmptyState
          title="No projects yet"
          description={
            mayCreate
              ? "Create the first one — a project is just a name, a key and a colour."
              : "Ask an admin to create one, or to add you to an existing project."
          }
        />
      ) : (
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {page.items.map((row) => (
            <ProjectCard
              key={row.project.id}
              project={row.project}
              stats={row.stats}
              href={`/${orgSlug}/projects/${row.project.slug}`}
              actor={actor}
            />
          ))}
        </div>
      )}
    </div>
  );
}
"use client";

/**
 * Page-number pagination control.
 *
 * Owner A — design system. The windowing arithmetic lives in
 * `./_lib/pagination-range` so it can be unit-tested without a DOM; this file
 * is the markup around it. `usePagination` in the hooks layer owns the state.
 */
import type { ReactElement } from "react";
import { cn } from "@/lib/cn";
import {
  buildPageRange,
  pageCount,
  rangeEnd,
  rangeStart,
} from "./_lib/pagination-range";
import { FOCUS_RING } from "./_lib/tokens";

export type PaginationProps = { page: number; perPage: number; total: number; onPageChange: (page: number) => void };

export function Pagination(props: PaginationProps): ReactElement | null {
  const { page, perPage, total, onPageChange } = props;

  const pages = pageCount(total, perPage);
  // One page of results needs no control at all — the summary line alone is
  // noise on a list that cannot be paged.
  if (pages <= 1) return null;

  const current = Math.min(Math.max(1, page), pages);
  const tokens = buildPageRange(current, pages);

  const go = (target: number) => {
    const next = Math.min(Math.max(1, target), pages);
    if (next !== current) onPageChange(next);
  };

  const stepClass = cn(
    "inline-flex h-8 items-center rounded-md border border-black/12 px-2.5 text-xs text-black/70",
    "hover:bg-surface-muted disabled:cursor-not-allowed disabled:opacity-45",
    FOCUS_RING,
  );

  return (
    <nav
      aria-label="Pagination"
      className="flex flex-wrap items-center justify-between gap-3"
    >
      <p className="text-xs text-black/55 dark:text-white/55">
        <span className="tabular-nums">{rangeStart(current, perPage, total)}</span>
        {"–"}
        <span className="tabular-nums">{rangeEnd(current, perPage, total)}</span>
        {" of "}
        <span className="tabular-nums">{total}</span>
      </p>

      <div className="flex items-center gap-1">
        <button
          type="button"
          onClick={() => go(current - 1)}
          disabled={current === 1}
          className={stepClass}
        >
          Previous
        </button>

        {tokens.map((token, index) =>
          token === "gap" ? (
            <span
              key={`gap-${index}`}
              aria-hidden="true"
              className="px-1 text-xs text-black/40"
            >
              …
            </span>
          ) : (
            <button
              key={token}
              type="button"
              aria-label={`Page ${token}`}
              aria-current={token === current ? "page" : undefined}
              onClick={() => go(token)}
              className={cn(
                "inline-flex h-8 min-w-8 items-center justify-center rounded-md px-2 text-xs tabular-nums",
                token === current
                  ? "bg-brand-500 font-medium text-white"
                  : "text-black/70 hover:bg-surface-muted dark:text-white/70",
                FOCUS_RING,
              )}
            >
              {token}
            </button>
          ),
        )}

        <button
          type="button"
          onClick={() => go(current + 1)}
          disabled={current === pages}
          className={stepClass}
        >
          Next
        </button>
      </div>
    </nav>
  );
}
